#!/usr/bin/env bash
set -euo pipefail
export PYTHONNOUSERSITE=1 PYTHONDONTWRITEBYTECODE=1

/data1/home/sunyiq/miniconda3/envs/knet_clean/bin/python -B - <<'PY'
import base64
import hashlib
import io
import json
import os
from pathlib import Path
import pwd
import stat
import zipfile

phase = Path('/data1/home/sunyiq/kalmannet_tukf09_scaled_noise_local_selection_remaining_453_20260930_attempt1/canary11')
parent = phase.parent
old = Path('/data1/home/sunyiq/kalmannet_tukf09_scaled_noise_rehearsal_20260922/full_budget_01142500_20260928_attempt1/bundle')
previous = Path('/data1/home/sunyiq/kalmannet_tukf09_scaled_noise_rehearsal_20260922/full_budget_01142500_20260929_attempt2/tukf09_full_budget_01142500_20260929.py')
expected_archive_sha = '2c7a78b80fe8e331cd37b43df010ddbbc776468f32d46baa99da051c2f5cf7f6'
expected_manifest_sha = 'c6cd14d7a72815e71dc4e3be9b679a04206029dbbd1f51beabd26fe47561f137'
canaries = (
    ('01052500', 7), ('01031500', 8), ('01162500', 9), ('01022500', 10),
    ('02202600', 11), ('02297310', 12), ('01139000', 13), ('02296500', 15),
    ('02108000', 17), ('04040500', 18), ('01411300', 20),
)

def digest_bytes(data):
    return hashlib.sha256(data).hexdigest()

def digest(path):
    with path.open('rb') as stream:
        return hashlib.file_digest(stream, 'sha256').hexdigest()

def exclusive_json(path, value):
    with path.open('x', encoding='utf-8') as stream:
        json.dump(value, stream, sort_keys=True, separators=(',', ':'), allow_nan=False)
        stream.write('\n')
        stream.flush()
        os.fsync(stream.fileno())

if pwd.getpwuid(os.getuid()).pw_name != 'sunyiq':
    raise SystemExit('wrong remote account')
if phase.exists() or phase.is_symlink():
    raise SystemExit('exclusive canary phase occupied before deployment')
if parent.exists() and (parent.is_symlink() or not parent.is_dir()):
    raise SystemExit('canary parent is linked or not a directory')
for path, expected in (
    (old / 'bundle_manifest.json', '4ebee2dcbd215e9751c86ca9895b84090956e7857d84b524fc87d60a3ea6afa1'),
    (old / 'hpc/tukf09_455_scaled_noise_common_v1.py', 'b4b70d97e4fdeca92ef1a7a8a6335a41d45acead5b40db5bdf1ab92ff70a3a5e'),
    (old / 'hpc/tukf09_455_scaled_noise_local_transfer_contract_v1.json', '27239212680bd370bd76f40e53337b7d68d80cbe4dc01feac2164bab4917f8a1'),
    (previous, '52a79db0169082449c8ea10548f957a7f1a38b4a9fdba84eefa96b5a188cf60a'),
):
    if path.is_symlink() or not path.is_file() or digest(path) != expected:
        raise SystemExit('sealed prerequisite changed: ' + str(path))
raw = base64.b64decode('', validate=True)
if digest_bytes(raw) != expected_archive_sha:
    raise SystemExit('canary staging archive fingerprint changed')
expected_names = {
    'payload_manifest.json', 'canary11_authorization.json', 'canary11_metadata.json',
    'canary11_training_validation.npz', 'tukf09_canary11_full_budget.py', 'canary11_full_budget.slurm',
}
with zipfile.ZipFile(io.BytesIO(raw)) as archive:
    infos = archive.infolist()
    names = [info.filename for info in infos]
    if len(names) != len(set(names)) or set(names) != expected_names:
        raise SystemExit('canary archive member set changed')
    for info in infos:
        if info.is_dir() or stat.S_IFMT(info.external_attr >> 16) not in (0, stat.S_IFREG):
            raise SystemExit('canary archive has nonregular member')
    data = {name: archive.read(name) for name in expected_names}
if digest_bytes(data['payload_manifest.json']) != expected_manifest_sha:
    raise SystemExit('canary payload manifest fingerprint changed')
manifest = json.loads(data['payload_manifest.json'])
expected_rows = [
    {'array_index': index, 'basin_id': basin, 'state_dimension': dimension}
    for index, (basin, dimension) in enumerate(canaries)
]
if (manifest.get('remote_phase') != phase.as_posix() or manifest.get('canaries') != expected_rows
        or manifest.get('maximum_scheduler_submissions') != 1
        or manifest.get('maximum_concurrent_tasks') != 4
        or manifest.get('wall_seconds_per_task') != 28800
        or manifest.get('formal_evaluation_authorized') is not False
        or manifest.get('transfer_library_authorized') is not False
        or manifest.get('automatic_retry_authorized') is not False
        or manifest.get('scientific_contract_changes_authorized') is not False
        or manifest.get('old_evidence_overwrite_authorized') is not False):
    raise SystemExit('canary payload scope changed')
if set(manifest.get('files', {})) != expected_names - {'payload_manifest.json'}:
    raise SystemExit('canary payload manifest member set changed')
for name in expected_names - {'payload_manifest.json'}:
    if manifest['files'][name] != {'sha256': digest_bytes(data[name]), 'size_bytes': len(data[name])}:
        raise SystemExit('canary payload member changed: ' + name)
parent.mkdir(mode=0o750, parents=True, exist_ok=False)
phase.mkdir(mode=0o750, exist_ok=False)
for name in ('logs', 'cache', 'tmp', 'control'):
    (phase / name).mkdir(mode=0o750, exist_ok=False)
for name in sorted(expected_names):
    with (phase / name).open('xb') as stream:
        stream.write(data[name])
        stream.flush()
        os.fsync(stream.fileno())
for index, (basin, dimension) in enumerate(canaries):
    control = phase / f'basin_{basin}' / 'control'
    control.mkdir(mode=0o750, parents=True, exist_ok=False)
    exclusive_json(control / 'deployment.json', {
        'status': 'CANARY11_BASIN_STAGED_NOT_SUBMITTED',
        'array_index': index, 'basin_id': basin, 'state_dimension': dimension,
        'archive_sha256': expected_archive_sha, 'manifest_sha256': expected_manifest_sha,
        'scheduler_submission_performed': False, 'model_execution_performed': False,
        'formal_evaluation_authorized': False, 'transfer_library_authorized': False,
    })
exclusive_json(phase / 'control/deployment.json', {
    'status': 'CANARY11_PAYLOAD_STAGED_NOT_SUBMITTED',
    'canary_count': len(canaries), 'maximum_concurrent_tasks': 4,
    'archive_sha256': expected_archive_sha, 'manifest_sha256': expected_manifest_sha,
    'scheduler_submission_performed': False, 'model_execution_performed': False,
    'formal_evaluation_authorized': False, 'transfer_library_authorized': False,
})
print('CANARY11_DEPLOYED_NOT_SUBMITTED ' + json.dumps({
    'phase': phase.as_posix(), 'canary_count': len(canaries),
    'archive_sha256': expected_archive_sha, 'manifest_sha256': expected_manifest_sha,
    'scheduler_submission_performed': False, 'model_execution_performed': False,
    'evaluation_array_reads': 0, 'formal_evaluation_performed': False,
}, sort_keys=True))
PY
